import math

def decide(view):
    # Diagnosis: Prior policy wasted an empty round by expanding completed leaves and relying on stale frontier state.
    # Replay reveals no new evidence for expanded leaves, causing redundant probes.
    # Changes: 1) Filter frontier to unexpanded leaves to prevent expanding already-expanded nodes.
    # 2) Explicitly stop on empty last_round to cut wasted rounds early.
    # 3) Use robust UCB with best_score fallback, handling null scores correctly.
    # 4) Track root expansion via history to avoid redundant re-attempts.

    frontier = view['frontier']
    if not frontier:
        return {'expand': [], 'stop': True}

    if view.get('last_round') and not view['last_round'].get('revealed_nodes'):
        return {'expand': [], 'stop': True}

    # Focus on unexpanded leaves to avoid wasting rounds on completed nodes
    candidates = [n for n in frontier if n.get('children_count', 0) == 0]
    if not candidates:
        return {'expand': [], 'stop': True}

    history_ids = [h.get('id') for h in view.get('history', [])]
    root_id = frontier[0]['id']
    root_expanded = root_id in history_ids

    total_visits = sum([n.get('children_count', 0) for n in frontier]) + len(frontier)
    if total_visits <= 1:
        total_visits = 2

    def priority(node):
        if node.get('depth', 0) == 0 and root_expanded:
            return -200.0
        score = node.get('score')
        if score is None:
            score = view.get('best_score') or 0.0
        visits = node.get('children_count', 0) + 1
        if visits <= 0:
            visits = 1
        return score + 1.41 * math.sqrt(math.log(total_visits) / visits)

    ranked = sorted(candidates, key=priority, reverse=True)
    return {'expand': [n['id'] for n in ranked[:2]], 'stop': False}
